#!/usr/bin/env node
// Signposts: a hidden `.<file>.h` beside each code file listing its functions, classes, routes and embedded-JS
// functions with line ranges, so an agent can read just the part of a file it needs. Local only (`.*.h` is
// gitignored), regenerated by Claude Code hooks (.claude/settings.json):
//   node signposts.mjs              PostToolUse: the edited file's path comes as JSON on stdin
//   node signposts.mjs --sync       SessionStart: create missing, refresh stale, delete orphaned signposts
//   node signposts.mjs <file>...    by hand, for the given files (prints what it wrote)
// It never fails a tool call: every error is swallowed and it always exits 0, printing nothing as a hook.

import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

const ROOT = path.resolve(process.env.CLAUDE_PROJECT_DIR || process.cwd());
const MAX_BYTES = 1_000_000;
const SKIP_DIRS = new Set(['build', '.gradle', '.kotlin', '.idea', 'node_modules', '.git', 'worktrees', 'xcuserdata']);

// One rule set per language. Each rule: a regex on a line, and how to name what it found.
const KOTLIN_MODS = String.raw`(?:(?:public|private|internal|protected|override|suspend|inline|operator|infix|tailrec|external|actual|expect|open|abstract|final|data|sealed|enum|annotation|inner|value|companion|fun)\s+)*`;
const LANGS = {
  kotlin: {
    ext: ['.kt', '.kts'],
    rules: [
      { re: new RegExp(String.raw`^\s*(?:@\w+(?:\([^)]*\))?\s+)*${KOTLIN_MODS}(fun|class|object|interface|typealias)\b(.*)$`), sig: m => m[1] + m[2] },
      { re: /^\s*companion\s+object\b(.*)$/, sig: m => 'companion object' + m[1] },
      // Ktor routes: get("/admin/series/{id}") { ... }
      { re: /^\s*(get|post|put|delete|patch|head|route|webSocket)\s*\(\s*"(\/[^"]*)"\s*\)\s*\{/, sig: m => `${m[1]}("${m[2]}")` },
    ],
  },
  swift: {
    ext: ['.swift'],
    rules: [{ re: /^\s*(?:@\w+(?:\([^)]*\))?\s+)*(?:(?:public|private|fileprivate|internal|open|final|static|class|override|mutating|nonisolated|convenience|required|async)\s+)*(func|init|deinit|class|struct|enum|protocol|extension|actor)\b(.*)$/, sig: m => m[1] + m[2] }],
  },
  c: {
    ext: ['.c', '.h', '.m'],
    rules: [
      // A definition or prototype starting in column 0: `type name(args...` with no statement keyword.
      { re: /^(?!(?:if|for|while|switch|return|else|do|typedef|#)\b)[A-Za-z_][\w\s\*]*?\b([A-Za-z_]\w*)\s*\([^;]*$/, sig: m => m[0] },
      { re: /^(?:typedef\s+)?(struct|enum|union)\s+(\w+)/, sig: m => `${m[1]} ${m[2]}` },
    ],
  },
  python: {
    ext: ['.py'],
    rules: [{ re: /^\s*((?:async\s+)?def|class)\s+(\w+.*)$/, sig: m => m[1] + ' ' + m[2] }],
  },
  shell: {
    ext: ['.sh'],
    rules: [{ re: /^\s*(?:function\s+)?([A-Za-z_][\w-]*)\s*\(\)\s*\{?/, sig: m => m[1] + '()' }],
  },
  js: {
    ext: ['.js', '.mjs', '.cjs', '.ts'],
    rules: JS_RULES(),
  },
};

function JS_RULES() {
  return [
    { re: /^\s*(?:export\s+)?(?:default\s+)?(?:async\s+)?function\s*\*?\s*([\w$]+)\s*\(.*$/, sig: m => 'function ' + m[0].trim().replace(/^.*?function\s*\*?\s*/, '') },
    { re: /^\s*(?:export\s+)?class\s+([\w$]+).*$/, sig: m => m[0].trim() },
    { re: /^\s*(?:export\s+)?(?:const|let|var)\s+([\w$]+)\s*=\s*(?:async\s+)?(?:function\b|\([^)]*\)\s*=>|[\w$]+\s*=>).*$/, sig: m => m[0].trim() },
  ];
}

const BY_EXT = new Map();
for (const [name, lang] of Object.entries(LANGS)) for (const e of lang.ext) BY_EXT.set(e, name);

/** `.<name>.h` beside the source. */
export const signpostPath = file => path.join(path.dirname(file), '.' + path.basename(file) + '.h');
const isSignpost = file => /^\..+\.h$/.test(path.basename(file));

function wanted(file) {
  if (isSignpost(file) || !BY_EXT.has(path.extname(file).toLowerCase())) return false;
  const rel = path.relative(ROOT, file);
  if (rel.startsWith('..') || path.isAbsolute(rel)) return false;
  return !rel.split(/[\\/]/).slice(0, -1).some(d => SKIP_DIRS.has(d));
}

// Joins a declaration that spans lines (an open parenthesis) into one signature, then drops the body: everything
// after the parameter list from its `{`, `=` or `=>` on (before any list, from a `{`).
function signature(lines, i, first) {
  let s = first, depth = 0;
  const count = t => { for (const ch of t) { if (ch === '(') depth++; else if (ch === ')') depth--; } };
  count(first);
  for (let k = i + 1; depth > 0 && k < lines.length && k < i + 10; k++) { s += ' ' + lines[k].trim(); count(lines[k]); }
  s = s.replace(/\s+/g, ' ');
  let cut = 0;
  const open = s.indexOf('(');
  if (open >= 0) {
    let d = 0;
    for (let k = open; k < s.length; k++) {
      if (s[k] === '(') d++;
      else if (s[k] === ')' && --d === 0) { cut = k + 1; break; }
    }
    if (cut === 0) cut = s.length;
  }
  s = (s.slice(0, cut) + s.slice(cut).replace(/\s*(=>|\{|=(?!=)|""").*$/, '')).trim();
  return s.length > 140 ? s.slice(0, 137) + '...' : s;
}

const indentOf = l => l.match(/^\s*/)[0].replace(/\t/g, '    ').length;

/** Every entry: { start, end, depth, sig } with 1-based inclusive lines. */
export function outline(text, lang) {
  const lines = text.split(/\r?\n/);
  const rules = LANGS[lang].rules, jsRules = JS_RULES();
  const found = [];
  // Kotlin raw strings holding embedded JS (`const val X_JS = """`): their functions are listed under them.
  let raw = null;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (raw) {
      if (line.includes('"""')) { raw.close = i; raw = null; continue; }
      for (const r of jsRules) {
        const m = line.match(r.re);
        if (m) { found.push({ i, indent: 0, sig: signature(lines, i, r.sig(m)), parent: raw }); break; }
      }
      continue;
    }
    if (lang === 'kotlin') {
      const c = line.match(/^\s*(?:private\s+|internal\s+)?const\s+val\s+(\w+)\s*=\s*"""(.*)$/);
      if (c) {
        // A string closed on its own line (maybe `+`-continued) is ranged like any entry; an open one holds JS.
        const open = !c[2].includes('"""');
        const entry = { i, indent: indentOf(line), sig: `const val ${c[1]}`, embedded: open, str: true };
        found.push(entry);
        if (open) { raw = entry; entry.close = lines.length - 1; }
        continue;
      }
    }
    for (const r of rules) {
      const m = line.match(r.re);
      if (m) { found.push({ i, indent: indentOf(line), sig: signature(lines, i, r.sig(m).trim()) }); break; }
    }
  }
  // A range runs to just before the next entry at the same or a shallower indent, less that entry's own comments,
  // annotations and blank lines. Embedded JS entries are ranged among themselves, inside their string.
  const lead = k => { while (k > 0 && /^\s*(\/\/|\/?\*|#(?!include)|@|$)/.test(lines[k - 1]) && !/"""/.test(lines[k - 1])) k--; return k; };
  for (let a = 0; a < found.length; a++) {
    const e = found[a];
    let end = e.embedded ? e.close : (e.parent ? e.parent.close - 1 : lines.length - 1);
    for (let b = a + 1; b < found.length; b++) {
      const n = found[b];
      if (n.parent !== e.parent) {
        if (e.parent) break;   // past the end of e's string: capped above
        continue;              // a JS function inside some string: never ends a Kotlin entry
      }
      if (n.indent <= e.indent) { end = Math.min(end, Math.max(e.i, lead(n.i) - 1)); break; }
    }
    while (end > e.i && /^\s*$/.test(lines[end])) end--;
    e.end = end;
  }
  return found.map(e => {
    // Nesting: the entries of the same kind (Kotlin, or JS in the same string) whose range holds this one, plus its string.
    const depth = found.filter(o => o !== e && o.i < e.i && o.end >= e.end && (o.parent === e.parent || o === e.parent)).length;
    const js = e.embedded && found.some(o => o.parent === e);
    return { start: e.i + 1, end: e.end + 1, depth, sig: e.sig + (e.str ? (js ? '   (embedded JS)' : '   (raw string)') : '') };
  });
}

export function render(file, text) {
  const lang = BY_EXT.get(path.extname(file).toLowerCase());
  const lines = text.split(/\r?\n/).length;
  const sha = createHash('sha1').update(text).digest('hex').slice(0, 12);
  const w = String(lines).length;
  const body = outline(text, lang).map(e => {
    const range = e.end > e.start ? `${String(e.start).padStart(w)}-${String(e.end).padEnd(w)}` : `${String(e.start).padStart(w)} ${' '.repeat(w)}`;
    return `${range}  ${'  '.repeat(e.depth)}${e.sig}`;
  });
  return `# ${path.basename(file)}: ${lines} lines · signposts · sha1 ${sha}\n` +
    `# Line ranges are inclusive; read just the range you need. A stale sha1 means the file changed since.\n` +
    body.join('\n') + '\n';
}

/** Writes the file's signpost if it changed; removes it when the source is gone. Returns true when it wrote. */
export function update(file) {
  const out = signpostPath(file);
  let st;
  try { st = fs.statSync(file); } catch { try { fs.unlinkSync(out); } catch {} return false; }
  if (!st.isFile() || st.size > MAX_BYTES) return false;
  const next = render(file, fs.readFileSync(file, 'utf8'));
  let prev = null;
  try { prev = fs.readFileSync(out, 'utf8'); } catch {}
  if (prev === next) return false;
  const tmp = out + '.' + process.pid + '.tmp';
  fs.writeFileSync(tmp, next);
  fs.renameSync(tmp, out);
  return true;
}

function sync() {
  const files = execFileSync('git', ['ls-files', '-co', '--exclude-standard'], { cwd: ROOT, encoding: 'utf8', maxBuffer: 64 << 20 })
    .split('\n').filter(Boolean).map(f => path.join(ROOT, f));
  const dirs = new Set();
  for (const f of files) {
    dirs.add(path.dirname(f));
    if (!wanted(f)) continue;
    try {
      const sp = fs.statSync(signpostPath(f), { throwIfNoEntry: false });
      if (!sp || sp.mtimeMs < fs.statSync(f).mtimeMs) update(f);
    } catch {}
  }
  // Orphans: a signpost whose source was deleted or renamed.
  for (const d of dirs) {
    let names = [];
    try { names = fs.readdirSync(d); } catch { continue; }
    for (const n of names) {
      if (!isSignpost(n)) continue;
      const src = path.join(d, n.slice(1, -2));
      if (!fs.existsSync(src)) try { fs.unlinkSync(path.join(d, n)); } catch {}
    }
  }
}

function fromHookInput() {
  let input = '';
  try { input = fs.readFileSync(0, 'utf8'); } catch { return; }
  const j = JSON.parse(input || '{}');
  const ti = j.tool_input || {};
  const file = ti.file_path || ti.notebook_path;
  if (file) { const abs = path.resolve(file); if (wanted(abs)) update(abs); }
}

try {
  const args = process.argv.slice(2);
  if (args[0] === '--sync') sync();
  else if (args.length) for (const a of args) { const abs = path.resolve(a); if (wanted(abs) && update(abs)) console.log('wrote ' + signpostPath(abs)); }
  else fromHookInput();
} catch {}
process.exit(0);
